		if len(summary.Sessions) > 0 {
			latestSessionIdx := len(summary.Sessions) - 1
			if spliceErr := spliceTasksTreeToV2(repo, v2Store, cpID, latestSessionIdx, rootTasksTree.Hash); spliceErr != nil {
