		if compacted != nil {
			opts.CompactTranscript = compacted
		} else if len(content.Transcript) > 0 {
			compactFailed = true
		}

		if writeErr := v2Store.WriteCommitted(ctx, opts); writeErr != nil {
			return fmt.Errorf("failed to write v2 session %d: %w", sessionIdx, writeErr)
